describe('Keyboard Navigation Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should navigate through all interactive elements using Tab key', () => {
        cy.get('body').tab(); // Focus on the first interactive element
        cy.focused().should('have.attr', 'tabindex'); // Check if the first element is focused

        cy.get('body').tab(); // Move to the next interactive element
        cy.focused().should('have.attr', 'tabindex'); // Check if the next element is focused

        // Repeat for as many interactive elements as necessary
        // Example for a button
        cy.get('button').first().should('be.visible').focus();
        cy.focused().should('have.text', 'Expected Button Text'); // Replace with actual button text
    });

    it('should loop back to the first interactive element after the last one', () => {
        const interactiveElementsCount = 5; // Replace with the actual count of interactive elements

        for (let i = 0; i < interactiveElementsCount; i++) {
            cy.get('body').tab(); // Tab through each interactive element
        }

        cy.focused().should('have.attr', 'tabindex'); // Check if the last element is focused
        cy.get('body').tab(); // Tab again to loop back to the first element
        cy.focused().should('have.attr', 'tabindex'); // Check if the first element is focused again
    });
});
